import java.util.*;public class Policy {public static Map<String,String> load(String text){var values=Parser.parse(text);if(!values.keySet().equals(Set.of("maxPlayers","motd")))throw new IllegalArgumentException();int count=Integer.parseInt(values.get("maxPlayers"));if(count<1||count>200||values.get("motd").isBlank())throw new IllegalArgumentException();return Map.copyOf(values);}}
